acceptance_tests_chirho.program_chirho:
scoreMaybe m = case m of { Nothing -> 0; Just x -> x }
scoreList xs = case xs of { a : b : [] -> a + b; _ -> 0 }
main = scoreMaybe ((do { Just x <- Just Nothing; return x }) :: Maybe Int) + scoreMaybe ((do { Just x <- Just (Just 3); return x }) :: Maybe Int) + scoreList ((do { Just x <- [Just 1, Nothing, Just 3]; return x }) :: [Int])

import Data.Monoid
score x = case x of { LT -> 1; EQ -> 2; GT -> 3 }
main = print (score (EQ <> LT) + score (GT <> LT) + score (mempty <> EQ) + score (mconcat [EQ, GT, LT]))

import Control.Applicative
scoreMaybe m = case m of { Nothing -> 0; Just x -> x }
main = length ((empty :: [Int]) <|> [1,2]) + length ([3] <|> [4,5]) + scoreMaybe ((empty :: Maybe Int) <|> Just 7) + scoreMaybe (Nothing <|> Just 11) + scoreMaybe (Just 13 <|> Just 17)

import Control.Monad
scoreMaybe m = case m of { Nothing -> 0; Just x -> x }
main = length (mzero :: [Int]) + scoreMaybe (mzero :: Maybe Int) + length (mplus (mzero :: [Int]) [1,2]) + length (mplus [3] [4,5]) + scoreMaybe (mplus (mzero :: Maybe Int) (Just 7)) + scoreMaybe (mplus Nothing (Just 11)) + scoreMaybe (mplus (Just 13) (Just 17))

import Control.Monad
scoreMaybe m = case m of { Nothing -> 0; Just x -> x }
main = scoreMaybe (fail "missing" :: Maybe Int) + length (fail "missing" :: [Int]) + scoreMaybe (mplus (fail "missing" :: Maybe Int) (Just 4)) + length (mplus (fail "missing" :: [Int]) [1,2])

import Data.Monoid
scoreMaybe m = case m of { Nothing -> 0; Just x -> x }
main = scoreMaybe (getFirst (First Nothing <> First (Just 4))) + scoreMaybe (getFirst (First (Just 7) <> First (Just 9))) + scoreMaybe (getFirst (mempty <> First (Just 5))) + scoreMaybe (getFirst (mconcat [First Nothing, First (Just 6), First (Just 8)])) + scoreMaybe (getLast (Last Nothing <> Last (Just 4))) + scoreMaybe (getLast (Last (Just 7) <> Last (Just 9))) + scoreMaybe (getLast (mempty <> Last (Just 5))) + scoreMaybe (getLast (mconcat [Last (Just 6), Last Nothing, Last (Just 8)]))
